    require(run.returncode == 0, "NEGATIVE_NONZERO\n" + run.stdout)
    require("Ran 40 tests" in run.stdout, "NEGATIVE_COUNT")
    require([line.strip() for line in run.stdout.splitlines()].count("OK") == 1, "NEGATIVE_OK")
